-- Direct Angular + Supabase. Existing relational content and revisions are preserved.
-- JSON values below are request/response values only; content stays in named columns.
create table if not exists portfolio_api.admins(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
alter table portfolio_api.admins enable row level security;
create or replace function portfolio_api.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from portfolio_api.admins where user_id=auth.uid()) $$;
create or replace function portfolio_api.require_admin() returns void language plpgsql stable security definer set search_path='' as $$ begin if not portfolio_api.is_admin() then raise exception 'Admin access required' using errcode='42501'; end if; end $$;
create or replace function portfolio_api.content_table(section text) returns text language plpgsql immutable set search_path='' as $$ begin return case section when 'profile' then 'profiles' when 'focus_items' then 'focus_items' when 'jobs' then 'experiences' when 'projects' then 'projects' when 'skill_groups' then 'skill_categories' when 'education' then 'education' when 'certificates' then 'certificates' when 'testimonials' then 'testimonials' when 'blog_posts' then 'blog_posts' else null end; end $$;
create or replace function portfolio_api.content_data(section text, item uuid) returns jsonb language plpgsql stable set search_path='' as $$ declare result jsonb; begin case section
when 'profile' then select jsonb_strip_nulls(jsonb_build_object('cta',jsonb_build_object('href',t.cta_href,'text',t.cta_text,'target',t.cta_target),'name',t.name,'brand',t.brand,'email',t.email,'phone',t.phone,'roles',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.profiles_roles c where c.profile_id=t.id),'[]'::jsonb),'stats',coalesce((select jsonb_agg(jsonb_build_object('number',c.stat_number,'description',c.description) order by c.position) from portfolio_api.profiles_stats c where c.profile_id=t.id),'[]'::jsonb),'teaser',t.teaser,'initial',t.initial,'socials',coalesce((select jsonb_agg(jsonb_build_object('title',c.title,'url',c.url,'icon',c.icon) order by c.position) from portfolio_api.profiles_socials c where c.profile_id=t.id),'[]'::jsonb),'imageAlt',t.image_alt,'imageSrc',t.image_src,'location',t.location,'og_image',t.og_image,'languages',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.profiles_languages c where c.profile_id=t.id),'[]'::jsonb),'seo_title',t.seo_title,'site_copy',coalesce((select jsonb_object_agg(c.selector,case when c.text_value is not null then to_jsonb(c.text_value) else jsonb_strip_nulls(jsonb_build_object('text',c.text_value,'html',c.html_value,'href',c.href_value,'src',c.src_value,'alt',c.alt_value,'title',c.title_value)) end) from portfolio_api.profile_site_copy c where c.profile_id=t.id),'{}'::jsonb),'hero_title',t.hero_title,'resumeLink',t.resume_link,'resume_url',t.resume_url,'description',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.profiles_description c where c.profile_id=t.id),'[]'::jsonb),'locationMap',t.location_map,'resume_mode',t.resume_mode,'soft_skills',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.profiles_soft_skills c where c.profile_id=t.id),'[]'::jsonb),'brand_suffix',t.brand_suffix,'nameWithBreak',t.name_with_break,'specialization',t.specialization,'seo_description',t.seo_description,'hero_description',t.hero_description,'resume_summary',t.resume_summary,'website',t.website,'slug',t.slug)) into result from portfolio_api.profiles t where t.id=item;
when 'focus_items' then select jsonb_strip_nulls(jsonb_build_object('tags',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.focus_items_tags c where c.focus_item_id=t.id),'[]'::jsonb),'image',t.image,'title',t.title,'imageAlt',t.image_alt,'description',t.description,'icon',t.icon,'slug',t.slug)) into result from portfolio_api.focus_items t where t.id=item;
when 'jobs' then select jsonb_strip_nulls(jsonb_build_object('date',t.date,'title',t.title,'vendor',t.vendor,'company',t.company,'location',t.location,'companyUrl',t.company_url,'contributions',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.experiences_contributions c where c.experience_id=t.id),'[]'::jsonb),'responsibilities',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.experiences_responsibilities c where c.experience_id=t.id),'[]'::jsonb),'contribution',t.contribution,'slug',t.slug)) into result from portfolio_api.experiences t where t.id=item;
when 'projects' then select jsonb_strip_nulls(jsonb_build_object('date',t.date,'name',t.name,'tags',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.projects_tags c where c.project_id=t.id),'[]'::jsonb),'links',jsonb_build_object('github',t.github_url,'github2',t.github_frontend_url,'live',t.live_url),'title',t.title,'client',t.client,'images',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.projects_images c where c.project_id=t.id),'[]'::jsonb),'status',t.status,'summary',t.summary,'visible',t.visible,'category',t.category,'features',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.projects_features c where c.project_id=t.id),'[]'::jsonb),'overview',t.overview,'in_resume',t.in_resume,'legacy_id',t.legacy_id,'comingSoon',t.coming_soon,'technologies',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.projects_technologies c where c.project_id=t.id),'[]'::jsonb),'extraFeatures',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.projects_extra_features c where c.project_id=t.id),'[]'::jsonb),'long_description',t.long_description,'link',t.link,'featured',t.featured,'description',t.description,'slug',t.slug)) into result from portfolio_api.projects t where t.id=item;
when 'skill_groups' then select jsonb_strip_nulls(jsonb_build_object('icon',t.icon,'names',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.skill_categories_names c where c.skill_categorie_id=t.id),'[]'::jsonb),'title',t.title,'description',t.description,'connections',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.skill_categories_connections c where c.skill_categorie_id=t.id),'[]'::jsonb),'slug',t.slug)) into result from portfolio_api.skill_categories t where t.id=item;
when 'education' then select jsonb_strip_nulls(jsonb_build_object('gpa',t.gpa,'url',t.url,'cgpa',t.cgpa,'date',t.date,'year',t.graduation_year,'title',t.title,'degree',t.degree,'location',t.location,'institution',t.institution,'institutionUrl',t.institution_url,'slug',t.slug)) into result from portfolio_api.education t where t.id=item;
when 'certificates' then select jsonb_strip_nulls(jsonb_build_object('url',t.url,'alt',t.alt,'date',t.date,'image',t.image,'theme',t.theme,'title',t.title,'issuer',t.issuer,'description',t.description,'slug',t.slug)) into result from portfolio_api.certificates t where t.id=item;
when 'testimonials' then select jsonb_strip_nulls(jsonb_build_object('name',t.name,'role',t.role,'quote',t.quote,'avatar',t.avatar,'visible',t.visible,'slug',t.slug)) into result from portfolio_api.testimonials t where t.id=item;
when 'blog_posts' then select jsonb_strip_nulls(jsonb_build_object('title',t.title,'excerpt',t.excerpt,'cover',t.cover,'tags',coalesce((select jsonb_agg(to_jsonb(c.item_text) order by c.position) from portfolio_api.blog_posts_tags c where c.blog_post_id=t.id),'[]'::jsonb),'content',t.content,'seo_title',t.seo_title,'seo_description',t.seo_description,'slug',t.slug,'published',t.published)) into result from portfolio_api.blog_posts t where t.id=item;
else raise exception 'Unknown section'; end case; return result; end $$;
create or replace function portfolio_api.write_content(section text, payload jsonb, item uuid default null, sort_order integer default 0, kind text default 'DRAFT', source uuid default null) returns uuid language plpgsql set search_path='' as $$
declare target uuid:=coalesce(item,gen_random_uuid()); old_version bigint; cols text[]; vals text[]; v jsonb; k text; begin
case section
when 'profile' then
insert into portfolio_api.profiles("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","cta_href","cta_text","cta_target","name","brand","email","phone","teaser","initial","image_alt","image_src","location","og_image","seo_title","hero_title","resume_link","resume_url","location_map","resume_mode","brand_suffix","name_with_break","specialization","seo_description","hero_description","resume_summary","website") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->'cta'->>'href',payload->'cta'->>'text',payload->'cta'->>'target',payload->>'name',payload->>'brand',payload->>'email',payload->>'phone',payload->>'teaser',payload->>'initial',payload->>'imageAlt',payload->>'imageSrc',payload->>'location',payload->>'og_image',payload->>'seo_title',payload->>'hero_title',payload->>'resumeLink',payload->>'resume_url',payload->>'locationMap',payload->>'resume_mode',payload->>'brand_suffix',payload->>'nameWithBreak',payload->>'specialization',payload->>'seo_description',payload->>'hero_description',payload->>'resume_summary',payload->>'website') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","cta_href"=excluded."cta_href","cta_text"=excluded."cta_text","cta_target"=excluded."cta_target","name"=excluded."name","brand"=excluded."brand","email"=excluded."email","phone"=excluded."phone","teaser"=excluded."teaser","initial"=excluded."initial","image_alt"=excluded."image_alt","image_src"=excluded."image_src","location"=excluded."location","og_image"=excluded."og_image","seo_title"=excluded."seo_title","hero_title"=excluded."hero_title","resume_link"=excluded."resume_link","resume_url"=excluded."resume_url","location_map"=excluded."location_map","resume_mode"=excluded."resume_mode","brand_suffix"=excluded."brand_suffix","name_with_break"=excluded."name_with_break","specialization"=excluded."specialization","seo_description"=excluded."seo_description","hero_description"=excluded."hero_description","resume_summary"=excluded."resume_summary","website"=excluded."website", version=profiles.version+1;
delete from portfolio_api.profiles_roles where profile_id=target;
insert into portfolio_api.profiles_roles(profile_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'roles','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.profiles_stats where profile_id=target;
insert into portfolio_api.profiles_stats(profile_id,position,stat_number,description) select target,(e.n-1)::integer,e.value->>'number',e.value->>'description' from jsonb_array_elements(coalesce(nullif(payload->'stats','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.profiles_socials where profile_id=target;
insert into portfolio_api.profiles_socials(profile_id,position,title,url,icon) select target,(e.n-1)::integer,e.value->>'title',e.value->>'url',e.value->>'icon' from jsonb_array_elements(coalesce(nullif(payload->'socials','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.profiles_languages where profile_id=target;
insert into portfolio_api.profiles_languages(profile_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'languages','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.profile_site_copy where profile_id=target;
insert into portfolio_api.profile_site_copy(profile_id,selector,text_value,html_value,href_value,src_value,alt_value,title_value) select target,e.key,case when jsonb_typeof(e.value)='string' then e.value#>>'{}' else e.value->>'text' end,e.value->>'html',e.value->>'href',e.value->>'src',e.value->>'alt',e.value->>'title' from jsonb_each(coalesce(nullif(payload->'site_copy','null'::jsonb),'{}'::jsonb)) e;
delete from portfolio_api.profiles_description where profile_id=target;
insert into portfolio_api.profiles_description(profile_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'description','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.profiles_soft_skills where profile_id=target;
insert into portfolio_api.profiles_soft_skills(profile_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'soft_skills','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
when 'focus_items' then
insert into portfolio_api.focus_items("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","image","title","image_alt","description","icon") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'image',payload->>'title',payload->>'imageAlt',payload->>'description',payload->>'icon') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","image"=excluded."image","title"=excluded."title","image_alt"=excluded."image_alt","description"=excluded."description","icon"=excluded."icon", version=focus_items.version+1;
delete from portfolio_api.focus_items_tags where focus_item_id=target;
insert into portfolio_api.focus_items_tags(focus_item_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'tags','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
when 'jobs' then
insert into portfolio_api.experiences("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","date","title","vendor","company","location","company_url","contribution") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'date',payload->>'title',payload->>'vendor',payload->>'company',payload->>'location',payload->>'companyUrl',payload->>'contribution') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","date"=excluded."date","title"=excluded."title","vendor"=excluded."vendor","company"=excluded."company","location"=excluded."location","company_url"=excluded."company_url","contribution"=excluded."contribution", version=experiences.version+1;
delete from portfolio_api.experiences_contributions where experience_id=target;
insert into portfolio_api.experiences_contributions(experience_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'contributions','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.experiences_responsibilities where experience_id=target;
insert into portfolio_api.experiences_responsibilities(experience_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'responsibilities','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
when 'projects' then
insert into portfolio_api.projects("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","date","name","github_url","github_frontend_url","live_url","title","client","status","summary","visible","category","overview","in_resume","legacy_id","coming_soon","long_description","link","featured","description") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'date',payload->>'name',payload->'links'->>'github',payload->'links'->>'github2',payload->'links'->>'live',payload->>'title',payload->>'client',payload->>'status',payload->>'summary',coalesce((payload->>'visible')::boolean,true),payload->>'category',payload->>'overview',coalesce((payload->>'in_resume')::boolean,true),payload->>'legacy_id',coalesce((payload->>'comingSoon')::boolean,false),payload->>'long_description',payload->>'link',coalesce((payload->>'featured')::boolean,false),payload->>'description') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","date"=excluded."date","name"=excluded."name","github_url"=excluded."github_url","github_frontend_url"=excluded."github_frontend_url","live_url"=excluded."live_url","title"=excluded."title","client"=excluded."client","status"=excluded."status","summary"=excluded."summary","visible"=excluded."visible","category"=excluded."category","overview"=excluded."overview","in_resume"=excluded."in_resume","legacy_id"=excluded."legacy_id","coming_soon"=excluded."coming_soon","long_description"=excluded."long_description","link"=excluded."link","featured"=excluded."featured","description"=excluded."description", version=projects.version+1;
delete from portfolio_api.projects_tags where project_id=target;
insert into portfolio_api.projects_tags(project_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'tags','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.projects_images where project_id=target;
insert into portfolio_api.projects_images(project_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'images','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.projects_features where project_id=target;
insert into portfolio_api.projects_features(project_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'features','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.projects_technologies where project_id=target;
insert into portfolio_api.projects_technologies(project_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'technologies','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.projects_extra_features where project_id=target;
insert into portfolio_api.projects_extra_features(project_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'extraFeatures','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
when 'skill_groups' then
insert into portfolio_api.skill_categories("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","icon","title","description") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'icon',payload->>'title',payload->>'description') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","icon"=excluded."icon","title"=excluded."title","description"=excluded."description", version=skill_categories.version+1;
delete from portfolio_api.skill_categories_names where skill_categorie_id=target;
insert into portfolio_api.skill_categories_names(skill_categorie_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'names','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
delete from portfolio_api.skill_categories_connections where skill_categorie_id=target;
insert into portfolio_api.skill_categories_connections(skill_categorie_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'connections','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
when 'education' then
insert into portfolio_api.education("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","gpa","url","cgpa","date","graduation_year","title","degree","location","institution","institution_url") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'gpa',payload->>'url',payload->>'cgpa',payload->>'date',payload->>'year',payload->>'title',payload->>'degree',payload->>'location',payload->>'institution',payload->>'institutionUrl') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","gpa"=excluded."gpa","url"=excluded."url","cgpa"=excluded."cgpa","date"=excluded."date","graduation_year"=excluded."graduation_year","title"=excluded."title","degree"=excluded."degree","location"=excluded."location","institution"=excluded."institution","institution_url"=excluded."institution_url", version=education.version+1;
when 'certificates' then
insert into portfolio_api.certificates("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","url","alt","date","image","theme","title","issuer","description") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'url',payload->>'alt',payload->>'date',payload->>'image',payload->>'theme',payload->>'title',payload->>'issuer',payload->>'description') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","url"=excluded."url","alt"=excluded."alt","date"=excluded."date","image"=excluded."image","theme"=excluded."theme","title"=excluded."title","issuer"=excluded."issuer","description"=excluded."description", version=certificates.version+1;
when 'testimonials' then
insert into portfolio_api.testimonials("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","name","role","quote","avatar","visible") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'name',payload->>'role',payload->>'quote',payload->>'avatar',coalesce((payload->>'visible')::boolean,true)) on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","name"=excluded."name","role"=excluded."role","quote"=excluded."quote","avatar"=excluded."avatar","visible"=excluded."visible", version=testimonials.version+1;
when 'blog_posts' then
insert into portfolio_api.blog_posts("id","created_at","updated_at","version","position","published","published_at","revision_kind","source_id","slug","title","excerpt","cover","content","seo_title","seo_description") values(target,now(),now(),0,sort_order,coalesce((payload->>'published')::boolean,false),case when (payload->>'published')::boolean then coalesce(nullif(payload->>'published_at','')::timestamptz,now()) else null end,kind,source,payload->>'slug',payload->>'title',payload->>'excerpt',payload->>'cover',payload->>'content',payload->>'seo_title',payload->>'seo_description') on conflict(id) do update set "updated_at"=excluded."updated_at","position"=excluded."position","published"=excluded."published","published_at"=excluded."published_at","revision_kind"=excluded."revision_kind","source_id"=excluded."source_id","slug"=excluded."slug","title"=excluded."title","excerpt"=excluded."excerpt","cover"=excluded."cover","content"=excluded."content","seo_title"=excluded."seo_title","seo_description"=excluded."seo_description", version=blog_posts.version+1;
delete from portfolio_api.blog_posts_tags where blog_post_id=target;
insert into portfolio_api.blog_posts_tags(blog_post_id,position,item_text) select target,(e.n-1)::integer,e.value#>>'{}' from jsonb_array_elements(coalesce(nullif(payload->'tags','null'::jsonb),'[]'::jsonb)) with ordinality e(value,n);
else raise exception 'Unknown section'; end case; return target; end $$;
create or replace function portfolio_api.remove_content(section text,item uuid) returns void language plpgsql set search_path='' as $$ begin case section
when 'profile' then delete from portfolio_api.profiles_roles where profile_id=item; delete from portfolio_api.profiles_stats where profile_id=item; delete from portfolio_api.profiles_socials where profile_id=item; delete from portfolio_api.profiles_languages where profile_id=item; delete from portfolio_api.profile_site_copy where profile_id=item; delete from portfolio_api.profiles_description where profile_id=item; delete from portfolio_api.profiles_soft_skills where profile_id=item; delete from portfolio_api.profiles where id=item;
when 'focus_items' then delete from portfolio_api.focus_items_tags where focus_item_id=item; delete from portfolio_api.focus_items where id=item;
when 'jobs' then delete from portfolio_api.experiences_contributions where experience_id=item; delete from portfolio_api.experiences_responsibilities where experience_id=item; delete from portfolio_api.experiences where id=item;
when 'projects' then delete from portfolio_api.projects_tags where project_id=item; delete from portfolio_api.projects_images where project_id=item; delete from portfolio_api.projects_features where project_id=item; delete from portfolio_api.projects_technologies where project_id=item; delete from portfolio_api.projects_extra_features where project_id=item; delete from portfolio_api.projects where id=item;
when 'skill_groups' then delete from portfolio_api.skill_categories_names where skill_categorie_id=item; delete from portfolio_api.skill_categories_connections where skill_categorie_id=item; delete from portfolio_api.skill_categories where id=item;
when 'education' then  delete from portfolio_api.education where id=item;
when 'certificates' then  delete from portfolio_api.certificates where id=item;
when 'testimonials' then  delete from portfolio_api.testimonials where id=item;
when 'blog_posts' then delete from portfolio_api.blog_posts_tags where blog_post_id=item; delete from portfolio_api.blog_posts where id=item;
else raise exception 'Unknown section'; end case; end $$;
create or replace function portfolio_api.content_rows(section text,kind text default 'DRAFT') returns jsonb language plpgsql stable set search_path='' as $$ declare result jsonb; tbl text:=portfolio_api.content_table(section); begin
if tbl is null then raise exception 'Unknown section'; end if;
execute format('select coalesce(jsonb_agg(jsonb_build_object(''id'',t.id,''data'',portfolio_api.content_data($1,t.id),''position'',t.position,''version'',t.version,''created_at'',t.created_at,''updated_at'',t.updated_at,''published_at'',t.published_at) order by t.position,t.created_at),''[]''::jsonb) from portfolio_api.%I t where revision_kind=$2',tbl) into result using section,kind; return result; end $$;
create or replace function portfolio_api.assemble(kind text) returns jsonb language plpgsql stable set search_path='' as $$ declare result jsonb:='{}'; entry record; rows jsonb; begin
for entry in select * from (values ('profile','profiles'),('focus_items','focus_items'),('jobs','experiences'),('projects','projects'),('skill_groups','skill_categories'),('education','education'),('certificates','certificates'),('testimonials','testimonials'),('blog_posts','blog_posts')) s(section,tbl) loop
if entry.section='blog_posts' then rows:='[]'; else
execute format('select coalesce(jsonb_agg(portfolio_api.content_data($1,id)||case when $1=''profile'' then ''{}''::jsonb else jsonb_build_object(''id'',coalesce(source_id,id)) end order by position,created_at),''[]''::jsonb) from portfolio_api.%I where revision_kind=$2',entry.tbl) into rows using entry.section,kind; end if;
result:=result||jsonb_build_object(entry.section,case when entry.section='profile' then coalesce(rows->0,'{}') else rows end); end loop; return result; end $$;
